#include <cstddef>
#include <cstdint>
namespace {constexpr std::uint64_t mask32=0xffffffffULL;void wide(std::uint64_t a,std::uint64_t b,std::uint64_t& hi,std::uint64_t& lo){auto a0=a&mask32,a1=a>>32,b0=b&mask32,b1=b>>32;auto p00=a0*b0,p01=a0*b1,p10=a1*b0,p11=a1*b1;lo=p00;auto old=lo;lo+=p01<<32;hi=p11+(p01>>32)+(lo<old);old=lo;lo+=p10<<32;hi+=(p10>>32)+(lo<old);}std::uint64_t mm(std::uint64_t a,std::uint64_t b,std::uint64_t m,std::uint64_t np){std::uint64_t th,tl,uh,ul;wide(a,b,th,tl);wide(tl*np,m,uh,ul);auto lo=tl+ul;auto hi=th+uh;if(lo<tl)++hi;bool ov=hi<th||(hi==th&&lo<tl);return (ov||hi>=m)?hi-m:hi;}std::uint64_t nprime(std::uint64_t m){std::uint64_t x=1;for(int i=0;i<6;i++)x*=2-m*x;return 0-x;}}
extern "C" std::int64_t embench_aha_mont64(const std::int64_t*v,std::size_t n){if(!v||n!=3||v[0]<0||v[1]<0||v[2]<3||(v[2]&1)==0)return -1;auto a=std::uint64_t(v[0]),b=std::uint64_t(v[1]),m=std::uint64_t(v[2]);if(a>=m||b>=m)return -1;auto np=nprime(m);return std::int64_t(mm(a,b,m,np));}
